using System.Text.Json;
using Quiberon.Simulation;
using Xunit;
public class SpecialistTests
{
    static Regiment U(string id,int uid=0,int army=0,Vec2? p=null)=>new(uid,army,id,Archetypes.Get(id),p??new(400,300),army==0?0:Math.PI);
    static BattleSimulation B(Regiment[] units,TerrainMap? t=null)=>new(units,new(){Width=1400,Height=1000,CombatEnabled=true,MoraleEnabled=true,CavalryEnabled=true,ArtilleryEnabled=true,SpecialistsEnabled=true},t,17);
    public static IEnumerable<object[]> Traits=>JsonDocument.Parse(File.ReadAllText(Path.Combine(AppContext.BaseDirectory,"artillery_fixtures/specialists.json"))).RootElement.EnumerateArray().Select(r=>new object[]{r.GetProperty("id").GetString()!,r.GetRawText()});
    [Theory,MemberData(nameof(Traits))]public void CurrentPythonTraitRulesMatch(string id,string json)
    {
        using var expected=JsonDocument.Parse(json);var b=B([U(id),U("infantry",1,1,new(480,300))],new(forests:[new(430,300,130,100,.6)]));var u=b.Units[0];u.Cohesion=85;u.ForestCover=b.Terrain.MovementEffect(u,Vec2.Zero).Forest;
        var sight=b.Combat.Sight(u,b.Units[1]);var movement=b.Terrain.MovementEffect(u,new(1,0));double skill=SpecialistSystem.WoodlandSkill(u.ForestCover);
        double outgoing=Math.Pow(sight.Transmission,1-(1-u.Archetype.ForestAim)*u.ForestCover)*Math.Max(.1,1-.45*u.ForestCover*u.Archetype.ForestFire*Math.Min(1,sight.Vegetation/40))*(1+(u.Archetype.ForestAccuracy-1)*skill);
        var result=new{id,reload=SpecialistSystem.Reload(u),formation=SpecialistSystem.FormationTime(u,7),manoeuvre=SpecialistSystem.Manoeuvre(u),aimed=SpecialistSystem.Aimed(u,sight.Transmission),visibility=new{visible=sight.Visible,transmission=sight.Transmission,vegetation=sight.Vegetation,reason=sight.Reason},forestPower=1+(u.Archetype.ForestMeleeDamage-1)*skill,forestShock=u.Archetype.MeleeShock*(1+(u.Archetype.ForestMeleeShock-1)*skill),outgoing,protection=Math.Max(.15,1-.60*b.Combat.ForestCover(b.Units[1])*Math.Min(1,sight.Vegetation/4)),movement=new{speed=movement.Speed,loss_per_metre=movement.LossPerMetre,forest=movement.Forest,slope=movement.Slope,grade=movement.Grade},guns=u.AvailableGuns};
        using var actual=JsonDocument.Parse(JsonSerializer.Serialize(result,ScenarioJson.Options));CombatReferenceTests.Compare(expected.RootElement,actual.RootElement,id);
    }
    [Fact]public void PrussianDrillScalesWithCohesionAndAffectsActualTransitions(){var b=B([U("prussian_line"),U("infantry",1,0,new(400,600))]);b.Units[0].Cohesion=90;Assert.Equal(9,SpecialistSystem.Reload(b.Units[0]));b.Issue(new(0,Formation:Formation.Column));b.Issue(new(1,Formation:Formation.Column));b.Step();Assert.True(b.Units[0].TransitionLeft<b.Units[1].TransitionLeft);b.Units[0].Cohesion=40;Assert.Equal(12,SpecialistSystem.Reload(b.Units[0]));}
    [Fact]public void WoodlandRegimentMovesFasterAndFightsBetterInCover(){var b=B([U("haudenosaunee_skirmishers"),U("infantry",1,1,new(450,300))],new(forests:[new(430,300,180,160,.8)]));var a=b.Units[0];var t=b.Units[1];Assert.True(b.Terrain.MovementEffect(a,new(1,0)).Speed>b.Terrain.MovementEffect(t,new(1,0)).Speed);double covered=b.Combat.CalculateMelee(a,t).Power;var open=B([U("haudenosaunee_skirmishers"),U("infantry",1,1,new(450,300))]);Assert.True(covered>open.Combat.CalculateMelee(open.Units[0],open.Units[1]).Power*2);Assert.True(b.Combat.CalculateVolley(a,t).Probability>b.Combat.CalculateVolley(t,a).Probability);}
    [Fact]public void ConcealmentIsObserverSpecificAndNeverBypassesRidge(){var b=B([U("haudenosaunee_skirmishers"),U("infantry",1,1,new(460,300))],new(forests:[new(430,300,120,100,.5)]));var a=b.Units[0];var t=b.Units[1];Assert.True(b.Combat.Sight(a,t).Transmission>b.Combat.Sight(t,a).Transmission);Assert.True(b.Combat.Sight(a,t).Visible);}
    [Fact]public void GrenadierAuraIsBoundedNonStackingAndInactiveWhenBroken(){double Run(int sources,bool broken=false){var units=new List<Regiment>{U("infantry")};units[0].Morale=50;for(int i=1;i<=sources;i++)units.Add(U("royal_grenadiers",i,0,new(350,300+i*20)));var b=B(units.ToArray());if(broken)foreach(var a in units.Skip(1))a.State=MoraleState.Routing;b.MoraleSystem.Update();return units[0].Morale-(.35+.08*(broken?0:sources))*.1;}Assert.Equal(Run(1),Run(3),8);Assert.Equal(50.022,Run(1),8);Assert.True(Run(1,true)<=50);}
    [Fact]public void RifleRangeAndAimedBonusRequireStationaryClearFire(){var b=B([U("revolutionary_rifles"),U("infantry",1,1,new(610,300))]);var a=b.Units[0];var t=b.Units[1];Assert.True(b.Combat.CanFire(a,t));Assert.False(b.Combat.CanFire(t,a));Assert.Equal(1.35,SpecialistSystem.Aimed(a,1),8);a.Speed=1;Assert.Equal(1,SpecialistSystem.Aimed(a,1));Assert.Equal(22,SpecialistSystem.Reload(a));Assert.True(b.Combat.Fire(a,t));Assert.Equal(22,a.ReloadLeft);}
    [Fact]public void UhlanBonusOnlyExploitsVulnerableTargets(){var b=B([U("commonwealth_uhlans"),U("infantry",1,1,new(490,300))]);var a=b.Units[0];var t=b.Units[1];a.Speed=8;Assert.Equal(1,SpecialistSystem.Exploit(a,t,false));t.State=MoraleState.Wavering;Assert.Equal(1.65,SpecialistSystem.Exploit(a,t,false));Assert.Equal(1,SpecialistSystem.Exploit(a,t,true));a.Speed=0;Assert.Equal(1,SpecialistSystem.Exploit(a,t,false));Assert.Equal(1.25,a.Archetype.Pursuit);}
    [Fact]public void AuraCannotCrossRidgeAndTraitsDoNotLeakIntoGenericUnits(){var b=B([U("infantry"),U("royal_grenadiers",1,0,new(500,300))],new([new(450,300,15,70,20,true)]));Assert.Null(SpecialistSystem.Support(b,b.Units[0]));Assert.Equal(0,SpecialistSystem.Drill(b.Units[0]));Assert.Equal(1,SpecialistSystem.Aimed(b.Units[0],1));Assert.Equal(1,SpecialistSystem.Manoeuvre(b.Units[0]));}
}
